"""FASTA/FASTQ reading and normalization.

Public API:

- :class:`SequenceRecord` — one sequence with identifier, description and
  optional per-base quality values.
- :func:`read_sequences` — lazily read records from a text path or text
  stream; the format is ``"fasta"``, ``"fastq"`` or ``"auto"``.
- :func:`write_sequences` — write records in FASTA or FASTQ form.

Sequences only contain the IUPAC DNA symbols ``ACGTRYSWKMBDHVN``.  FASTQ
quality values use the Phred+33 encoding with ASCII characters 33–126.
"""

from __future__ import annotations

import io
import os
from collections.abc import Iterable, Iterator
from dataclasses import dataclass

__all__ = [
    "SequenceRecord",
    "SequenceFormatError",
    "SequenceValidationError",
    "read_sequences",
    "write_sequences",
]

_VALID_BASES = frozenset("ACGTRYSWKMBDHVN")
_INPUT_FORMATS = ("fasta", "fastq", "auto")
_OUTPUT_FORMATS = ("fasta", "fastq")


class SequenceFormatError(ValueError):
    """Malformed FASTA/FASTQ input (structure, identifiers, lengths)."""


class SequenceValidationError(ValueError):
    """A sequence contains a symbol outside the allowed IUPAC set."""


@dataclass(frozen=True)
class SequenceRecord:
    """A single sequence record.

    ``identifier`` is the first whitespace-delimited field of the title
    line; ``description`` holds the remainder (``""`` when absent).
    ``quality`` is ``None`` for FASTA records and a tuple of Phred scores
    for FASTQ records.
    """

    identifier: str
    sequence: str
    description: str = ""
    quality: tuple[int, ...] | None = None


def _clean_sequence(raw: str) -> str:
    """Strip in-line whitespace and upper-case a raw sequence fragment."""
    return "".join(raw.split()).upper()


def _validate_sequence(identifier: str, sequence: str) -> None:
    for position, symbol in enumerate(sequence, start=1):
        if symbol not in _VALID_BASES:
            raise SequenceValidationError(
                f"record {identifier!r}: invalid symbol {symbol!r} at position {position}"
            )


def _split_title(title: str, source: str, line_number: int) -> tuple[str, str]:
    fields = title.split(None, 1)
    if not fields:
        raise SequenceFormatError(f"{source}:{line_number}: empty sequence identifier")
    identifier = fields[0]
    description = fields[1] if len(fields) == 2 else ""
    return identifier, description


def _line_error(source: str, line_number: int, message: str) -> SequenceFormatError:
    return SequenceFormatError(f"{source}:{line_number}: {message}")


def _fasta_records(
    lines: Iterator[tuple[int, str]], source: str
) -> Iterator[SequenceRecord]:
    header_line: str | None = None
    header_number = 0
    seq_parts: list[str] = []

    for number, raw_line in lines:
        line = raw_line.rstrip("\r\n")
        if line.startswith(">"):
            if header_line is not None:
                yield _finish_fasta(header_line, header_number, seq_parts, source)
            header_line = line
            header_number = number
            seq_parts = []
        elif line.strip():
            if header_line is None:
                raise _line_error(
                    source,
                    number,
                    "content before first title line (expected a line starting with '>')",
                )
            seq_parts.append(line)
        # Blank lines outside or inside a record are ignored.

    if header_line is not None:
        yield _finish_fasta(header_line, header_number, seq_parts, source)


def _finish_fasta(
    header_line: str, header_number: int, parts: list[str], source: str
) -> SequenceRecord:
    identifier, description = _split_title(header_line[1:], source, header_number)
    sequence = _clean_sequence("".join(parts))
    if not sequence:
        raise _line_error(source, header_number, "empty sequence")
    _validate_sequence(identifier, sequence)
    return SequenceRecord(identifier, sequence, description)


def _check_quality_segment(segment: str, source: str, line_number: int) -> None:
    for char in segment:
        value = ord(char)
        if value < 33 or value > 126:
            raise _line_error(
                source,
                line_number,
                f"quality character {char!r} is outside the ASCII 33-126 range",
            )


def _fastq_records(
    lines: Iterator[tuple[int, str]], source: str
) -> Iterator[SequenceRecord]:
    # State machine over logical lines.  Sequence and quality may each
    # span several physical lines; record boundaries are determined by the
    # '+' separator and the number of quality characters matching the
    # sequence length.
    header_line: str | None = None
    header_number = 0
    seq_parts: list[str] = []
    qual_segments: list[str] = []
    in_quality = False

    for number, raw_line in lines:
        line = raw_line.rstrip("\r\n")

        if header_line is None:
            if not line:
                raise _line_error(
                    source,
                    number,
                    "incomplete FASTQ record (expected a title line starting with '@')",
                )
            if not line.startswith("@"):
                raise _line_error(
                    source, number, "expected a FASTQ title line starting with '@'"
                )
            header_line = line
            header_number = number
            seq_parts = []
            qual_segments = []
            in_quality = False
            continue

        if not in_quality:
            if line.startswith("+"):
                plus_title = line[1:]
                if plus_title and plus_title != header_line[1:]:
                    raise _line_error(
                        source,
                        number,
                        "FASTQ separator title does not match the record title",
                    )
                if not _clean_sequence("".join(seq_parts)):
                    raise _line_error(source, header_number, "empty sequence")
                in_quality = True
            else:
                if not line.strip():
                    raise _line_error(source, number, "empty sequence")
                seq_parts.append(line)
            continue

        if not line:
            raise _line_error(source, number, "incomplete FASTQ record (missing quality values)")
        _check_quality_segment(line, source, number)
        qual_segments.append(line)

        sequence = _clean_sequence("".join(seq_parts))
        quality_text = "".join(qual_segments)
        if len(quality_text) > len(sequence):
            raise _line_error(
                source,
                number,
                f"quality length {len(quality_text)} does not match sequence length {len(sequence)}",
            )
        if len(quality_text) == len(sequence):
            yield _finish_fastq(
                header_line, header_number, sequence, quality_text, source
            )
            header_line = None

    if header_line is not None:
        raise _line_error(source, header_number, "incomplete FASTQ record")


def _finish_fastq(
    header_line: str,
    header_number: int,
    sequence: str,
    quality_text: str,
    source: str,
) -> SequenceRecord:
    identifier, description = _split_title(header_line[1:], source, header_number)
    if not sequence:
        raise _line_error(source, header_number, "empty sequence")
    _validate_sequence(identifier, sequence)
    if len(quality_text) != len(sequence):
        raise _line_error(
            source,
            header_number,
            f"quality length {len(quality_text)} does not match sequence length {len(sequence)}",
        )
    quality = tuple(ord(char) - 33 for char in quality_text)
    return SequenceRecord(identifier, sequence, description, quality)


def _enumerate_lines(stream: Iterable[str]) -> Iterator[tuple[int, str]]:
    for number, line in enumerate(stream, start=1):
        yield number, line


def read_sequences(
    source: "str | os.PathLike[str] | io.TextIOBase",
    format: str = "auto",
) -> Iterator[SequenceRecord]:
    """Lazily read sequence records from *source*.

    *source* is either a filesystem path (``str`` or :class:`os.PathLike`)
    or an already-open text stream.  *format* is ``"fasta"``, ``"fastq"``
    or ``"auto"``; with ``"auto"`` the format is detected from the first
    non-empty line (``>`` → FASTA, ``@`` → FASTQ).

    Records are produced in input order.  Errors raised while opening a
    path propagate as :class:`OSError`; malformed input raises
    :class:`SequenceFormatError` or :class:`SequenceValidationError`
    during iteration and are never swallowed.
    """
    if format not in _INPUT_FORMATS:
        raise ValueError(
            f"unsupported format {format!r}; expected one of {', '.join(_INPUT_FORMATS)}"
        )

    if isinstance(source, io.IOBase):
        stream: io.TextIOBase = source
        source_name = getattr(stream, "name", None)
        if not isinstance(source_name, str) or not source_name:
            source_name = "<stream>"
        close = False
    elif isinstance(source, (str, os.PathLike)):
        path = os.fspath(source)
        stream = open(path, "r", encoding="utf-8", newline="")
        source_name = path
        close = True
    else:
        raise TypeError("source must be a text path or a text stream")

    try:
        yield from _read_from_stream(stream, source_name, format)
    finally:
        if close:
            stream.close()


def _read_from_stream(
    stream: Iterable[str], source_name: str, format: str
) -> Iterator[SequenceRecord]:
    numbered = _enumerate_lines(stream)

    first_number = 0
    first_line: str | None = None
    for number, raw_line in numbered:
        candidate = raw_line.rstrip("\r\n")
        if candidate.strip():
            first_number = number
            first_line = candidate
            break

    if first_line is None:
        if format == "auto":
            raise SequenceFormatError(
                f"{source_name}: empty input; cannot determine format"
            )
        raise SequenceFormatError(f"{source_name}: empty input")

    if format == "auto":
        if first_line.startswith(">"):
            detected = "fasta"
        elif first_line.startswith("@"):
            detected = "fastq"
        else:
            raise _line_error(
                source_name,
                first_number,
                "cannot determine format: first non-empty line must start with '>' or '@'",
            )
    else:
        detected = format

    def replay() -> Iterator[tuple[int, str]]:
        yield first_number, first_line + "\n"
        yield from numbered

    # The per-format parsers reject a first line that lacks their title
    # marker themselves (reported as content before / unexpected title).
    if detected == "fasta":
        yield from _fasta_records(replay(), source_name)
    else:
        yield from _fastq_records(replay(), source_name)


def write_sequences(
    records: Iterable[SequenceRecord],
    output: "str | os.PathLike[str] | io.TextIOBase",
    format: str = "fasta",
    line_width: int = 60,
) -> None:
    """Write *records* to *output* in FASTA or FASTQ form.

    FASTA sequences are wrapped at *line_width* characters (a positive
    integer); FASTQ always uses the fixed four-line layout regardless of
    *line_width*.  Records without quality values cannot be written as
    FASTQ.  Output uses ``"\\n"`` line endings and ends with exactly one
    trailing newline.
    """
    if format not in _OUTPUT_FORMATS:
        raise ValueError(f"unsupported format {format!r}; expected 'fasta' or 'fastq'")
    if not isinstance(line_width, int) or isinstance(line_width, bool) or line_width <= 0:
        raise ValueError("line_width must be a positive integer")

    if isinstance(output, io.IOBase):
        stream: io.TextIOBase = output
        close = False
    elif isinstance(output, (str, os.PathLike)):
        stream = open(os.fspath(output), "w", encoding="utf-8", newline="")
        close = True
    else:
        raise TypeError("output must be a text path or a text stream")

    try:
        for record in records:
            _validate_sequence(record.identifier, record.sequence)
            if format == "fasta":
                stream.write(_format_fasta_record(record, line_width))
            else:
                stream.write(_format_fastq_record(record))
    finally:
        if close:
            stream.close()


def _format_title(record: SequenceRecord) -> str:
    if record.description:
        return record.identifier + " " + record.description
    return record.identifier


def _format_fasta_record(record: SequenceRecord, line_width: int) -> str:
    parts = [">" + _format_title(record) + "\n"]
    sequence = record.sequence
    for start in range(0, len(sequence), line_width):
        parts.append(sequence[start : start + line_width])
        parts.append("\n")
    return "".join(parts)


def _format_fastq_record(record: SequenceRecord) -> str:
    if record.quality is None:
        raise ValueError(
            f"record {record.identifier!r} has no quality values; cannot write it as FASTQ"
        )
    if len(record.quality) != len(record.sequence):
        raise ValueError(
            f"record {record.identifier!r}: quality length does not match sequence length"
        )
    quality_chars = []
    for value in record.quality:
        if not 0 <= value <= 93:
            raise ValueError(
                f"record {record.identifier!r}: quality score {value} is outside the "
                "Phred+33 range 0-93"
            )
        quality_chars.append(chr(value + 33))
    title = _format_title(record)
    return f"@{title}\n{record.sequence}\n+{title}\n{''.join(quality_chars)}\n"

"""Reference-aware VCF reading, normalization and writing.

Public API:

- :class:`VcfHeader` — the ``##`` meta-information lines (kept verbatim
  and in order) together with the sample names declared by the single
  ``#CHROM`` column header.
- :class:`VcfRecord` — one VCF data row: the eight fixed columns, an
  optional ``FORMAT`` column and the per-sample text columns.
- :class:`VcfFile` — a parsed VCF document pairing a header with its
  records.
- :func:`read_vcf` — parse VCF text from a path or text stream.
- :func:`normalize_record` / :func:`normalize_vcf` — trim common
  allele suffixes/prefixes and left-align indels against a reference.
- :func:`render_vcf` / :func:`write_vcf` — serialize a VCF document
  with tabs and ``"\\n"``.

Ordinary sequence alleles only contain the IUPAC DNA symbols
``ACGTRYSWKMBDHVN`` (lower-case input is upper-cased).  Records carrying
symbolic (``<...>``), break-end (brackets or a ``.`` join), spanning
(``*``) or missing (``.``) ALT alleles are validated against the
reference but never trimmed or shifted.
"""

from __future__ import annotations

import io
import os
from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass, replace

from .sequence_io import SequenceRecord, _VALID_BASES

__all__ = [
    "VcfHeader",
    "VcfRecord",
    "VcfFile",
    "VcfFormatError",
    "ReferenceMismatchError",
    "read_vcf",
    "normalize_record",
    "normalize_vcf",
    "render_vcf",
    "write_vcf",
]

_FIXED_COLUMNS = ("#CHROM", "POS", "ID", "REF", "ALT", "QUAL", "FILTER", "INFO")
_MIN_COLUMNS = 8


class VcfFormatError(ValueError):
    """Malformed VCF input (missing/duplicate header, bad columns or fields)."""


class ReferenceMismatchError(ValueError):
    """A record's CHROM is absent/duplicated in the reference or REF disagrees."""


@dataclass(frozen=True)
class VcfHeader:
    """The VCF header.

    ``meta_lines`` holds the ``##`` meta-information lines verbatim,
    without their line terminators and in input order.  ``samples``
    holds the sample names taken from the single ``#CHROM`` header line
    (an empty tuple for sample-less VCF).
    """

    meta_lines: tuple[str, ...] = ()
    samples: tuple[str, ...] = ()

    @property
    def column_names(self) -> tuple[str, ...]:
        """All column names as declared by the ``#CHROM`` line."""
        if self.samples:
            return _FIXED_COLUMNS + ("FORMAT",) + self.samples
        return _FIXED_COLUMNS


@dataclass(frozen=True)
class VcfRecord:
    """One VCF data row.

    The fixed columns are ``chrom``, ``pos`` (1-based), ``id``, ``ref``,
    ``alt`` (a tuple of ALT allele strings), ``qual``, ``filter`` and
    ``info``.  For a VCF with samples, ``format_text`` holds the FORMAT
    string and ``sample_text`` one verbatim column per sample; both are
    empty for sample-less VCF.  ``line_number`` is the 1-based source
    line of a parsed record (``0`` for records built directly).
    """

    chrom: str
    pos: int
    id: str
    ref: str
    alt: tuple[str, ...]
    qual: str
    filter: str
    info: str
    format_text: str | None = None
    sample_text: tuple[str, ...] = ()
    line_number: int = 0

    @property
    def alt_text(self) -> str:
        """The ALT column as it appears on disk."""
        return ",".join(self.alt)


@dataclass(frozen=True)
class VcfFile:
    """A parsed VCF document: a header and its records in input order.

    ``source`` is the path or stream label the document was read from
    and is used to qualify error messages during normalization.
    """

    header: VcfHeader
    records: tuple[VcfRecord, ...] = ()
    source: str = ""


def _line_error(source: str, line_number: int, message: str) -> VcfFormatError:
    return VcfFormatError(f"{source}:{line_number}: {message}")


def _is_plain_allele(allele: str) -> bool:
    """Whether *allele* is an ordinary sequence allele of real bases.

    The gVCF spanning value ``*``, the missing value ``.``, symbolic
    alleles (``<DEL>``) and break-end alleles (``]chr:123]N``, ``N.``)
    are not plain.
    """
    if not allele or allele == "*" or allele == ".":
        return False
    if "<" in allele or ">" in allele:
        return False
    if "[" in allele or "]" in allele or "." in allele or "*" in allele:
        return False
    return True


def _validate_allele(allele: str) -> str:
    """Upper-case and validate one ordinary sequence allele."""
    upper = allele.upper()
    for offset, symbol in enumerate(upper):
        if symbol not in _VALID_BASES:
            raise ValueError(
                f"invalid allele symbol {symbol!r} at offset {offset} of {allele!r}"
            )
    return upper


def _parse_pos(pos_text: str, source: str, number: int) -> int:
    if not pos_text or any(char < "0" or char > "9" for char in pos_text):
        raise _line_error(
            source, number, f"POS {pos_text!r} is not a positive integer"
        )
    pos = int(pos_text)
    if pos <= 0:
        raise _line_error(
            source, number, f"POS {pos_text!r} is not a positive integer"
        )
    return pos


def _parse_record_line(
    line: str, number: int, source: str, samples: Sequence[str]
) -> VcfRecord:
    fields = line.split("\t")
    if len(fields) < _MIN_COLUMNS:
        raise _line_error(
            source,
            number,
            f"expected at least 8 tab-separated columns, got {len(fields)}",
        )
    if samples:
        expected = _MIN_COLUMNS + 1 + len(samples)
        if len(fields) != expected:
            raise _line_error(
                source,
                number,
                f"expected {expected} columns to match the #CHROM header, got {len(fields)}",
            )
        format_text = fields[8]
        if not format_text:
            raise _line_error(source, number, "empty FORMAT column")
        sample_text = tuple(fields[9:])
    else:
        if len(fields) != _MIN_COLUMNS:
            raise _line_error(
                source,
                number,
                f"expected 8 columns to match the sample-less #CHROM header, "
                f"got {len(fields)}",
            )
        format_text = None
        sample_text = ()

    chrom, pos_text, ident, ref_text, alt_text, qual, flt, info = fields[:8]

    if not chrom:
        raise _line_error(source, number, "empty CHROM column")
    pos = _parse_pos(pos_text, source, number)

    if not ref_text:
        raise _line_error(source, number, "empty REF allele")
    try:
        ref = _validate_allele(ref_text)
    except ValueError as exc:
        raise _line_error(source, number, str(exc)) from None

    if not alt_text:
        raise _line_error(source, number, "empty ALT column")
    alts: list[str] = []
    for allele in alt_text.split(","):
        if allele == "":
            raise _line_error(source, number, "empty ALT allele")
        if not _is_plain_allele(allele):
            alts.append(allele)
            continue
        try:
            alts.append(_validate_allele(allele))
        except ValueError as exc:
            raise _line_error(source, number, str(exc)) from None

    return VcfRecord(
        chrom=chrom,
        pos=pos,
        id=ident,
        ref=ref,
        alt=tuple(alts),
        qual=qual,
        filter=flt,
        info=info,
        format_text=format_text,
        sample_text=sample_text,
        line_number=number,
    )


def _parse_header_line(
    line: str, number: int, source: str
) -> tuple[str, ...]:
    """Validate the ``#CHROM`` line and return its sample names."""
    columns = line.split("\t")
    if tuple(columns[:8]) != _FIXED_COLUMNS:
        raise _line_error(
            source,
            number,
            "the first eight #CHROM header columns must be exactly "
            "#CHROM\\tPOS\\tID\\tREF\\tALT\\tQUAL\\tFILTER\\tINFO",
        )
    tail = columns[8:]
    if not tail:
        return ()
    if tail[0] != "FORMAT":
        raise _line_error(
            source, number, "the ninth column, when present, must be FORMAT"
        )
    samples = tuple(tail[1:])
    if not samples:
        raise _line_error(source, number, "FORMAT column requires at least one sample")
    if any(not sample for sample in samples):
        raise _line_error(source, number, "empty sample name in #CHROM header")
    return samples


def read_vcf(
    source: "str | os.PathLike[str] | io.TextIOBase",
) -> VcfFile:
    """Read and validate a whole VCF document from *source*.

    *source* is either a filesystem path (``str`` or :class:`os.PathLike`)
    or an already-open text stream.  ``##`` meta-information lines are
    kept verbatim and in order; exactly one legal ``#CHROM`` line is
    required and every data row must match its columns.  Records are
    returned in input order.

    Raises :class:`VcfFormatError` for malformed input and :class:`OSError`
    when opening a path fails.
    """
    if isinstance(source, io.IOBase):
        stream: io.TextIOBase = source
        source_name = getattr(stream, "name", None)
        if not isinstance(source_name, str) or not source_name:
            source_name = "<stream>"
        close = False
    elif isinstance(source, (str, os.PathLike)):
        path = os.fspath(source)
        stream = open(path, "r", encoding="utf-8", newline="")
        source_name = path
        close = True
    else:
        raise TypeError("source must be a text path or a text stream")

    try:
        meta_lines: list[str] = []
        samples: tuple[str, ...] | None = None
        records: list[VcfRecord] = []

        for number, raw_line in enumerate(stream, start=1):
            line = raw_line.rstrip("\r\n")
            if line.startswith("##"):
                if samples is not None:
                    raise _line_error(
                        source_name,
                        number,
                        "meta-information line after the #CHROM header",
                    )
                meta_lines.append(line)
            elif line.startswith("#"):
                if samples is not None:
                    raise _line_error(
                        source_name, number, "duplicate #CHROM column header"
                    )
                samples = _parse_header_line(line, number, source_name)
            else:
                if samples is None:
                    raise _line_error(
                        source_name, number, "data row before the #CHROM column header"
                    )
                records.append(
                    _parse_record_line(line, number, source_name, samples)
                )

        if samples is None:
            raise VcfFormatError(
                f"{source_name}:1: missing #CHROM column header"
            )
        return VcfFile(
            VcfHeader(tuple(meta_lines), samples), tuple(records), source_name
        )
    finally:
        if close:
            stream.close()


def _build_reference(
    reference: Iterable[SequenceRecord],
) -> tuple[dict[str, str], set[str]]:
    """Map CHROM to sequence, tracking identifiers appearing more than once."""
    sequences: dict[str, str] = {}
    duplicates: set[str] = set()
    for record in reference:
        if record.identifier in sequences:
            duplicates.add(record.identifier)
        else:
            sequences[record.identifier] = record.sequence
    return sequences, duplicates


def _record_error(source: str, record: VcfRecord, message: str) -> VcfFormatError:
    if source and record.line_number:
        return VcfFormatError(f"{source}:{record.line_number}: {message}")
    if record.line_number:
        return VcfFormatError(f"line {record.line_number}: {message}")
    return VcfFormatError(message)


def _resolve_chromosome(
    record: VcfRecord,
    sequences: Mapping[str, str],
    duplicates: set[str],
) -> str:
    if record.chrom in duplicates:
        raise ReferenceMismatchError(
            f"CHROM {record.chrom} POS {record.pos}: CHROM occurs more than once "
            "in the reference"
        )
    try:
        return sequences[record.chrom]
    except KeyError:
        raise ReferenceMismatchError(
            f"CHROM {record.chrom} POS {record.pos}: no matching record in the reference"
        ) from None


def _minimize(
    pos: int, ref: str, alts: Sequence[str]
) -> tuple[int, str, tuple[str, ...]]:
    """Remove the common suffix and prefix shared by all alleles.

    At least one base is always retained per allele and *pos* (1-based)
    is advanced by the number of stripped leading bases.
    """
    # Common suffix: compare each ALT against REF up to the shorter
    # length, always leaving at least one base per allele.
    suffix = 0
    while True:
        index = len(ref) - 1 - suffix
        if index <= 0:
            break
        ref_base = ref[index]
        ok = True
        for alt in alts:
            alt_index = len(alt) - 1 - suffix
            if alt_index <= 0 or alt[alt_index] != ref_base:
                ok = False
                break
        if not ok:
            break
        suffix += 1
    if suffix:
        ref = ref[: len(ref) - suffix]
        alts = tuple(alt[: len(alt) - suffix] for alt in alts)

    # Common prefix: at least one base must remain in every allele.
    prefix = 0
    shortest = min(len(ref), min(len(alt) for alt in alts))
    while prefix < shortest - 1 and all(
        alt[prefix] == ref[prefix] for alt in alts
    ):
        prefix += 1
    if prefix:
        ref = ref[prefix:]
        alts = tuple(alt[prefix:] for alt in alts)
        pos += prefix

    return pos, ref, tuple(alts)


def _lengths_differ(ref: str, alts: Sequence[str]) -> bool:
    return any(len(alt) != len(ref) for alt in alts)


def _normalize_against(
    record: VcfRecord,
    sequences: Mapping[str, str],
    duplicates: set[str],
    source: str,
) -> VcfRecord:
    chromosome = _resolve_chromosome(record, sequences, duplicates)

    end = record.pos - 1 + len(record.ref)
    if record.pos < 1 or end > len(chromosome):
        raise _record_error(
            source,
            record,
            f"CHROM {record.chrom} POS {record.pos}: REF of length {len(record.ref)} "
            f"is out of bounds for a reference of length {len(chromosome)}",
        )

    expected = chromosome[record.pos - 1 : end].upper()
    if expected != record.ref:
        raise ReferenceMismatchError(
            f"CHROM {record.chrom} POS {record.pos}: REF does not match the "
            f"reference: expected {expected!r}, found {record.ref!r}"
        )

    if not all(_is_plain_allele(allele) for allele in record.alt):
        # Symbolic, break-end, spanning or missing ALT: verify only.
        return record

    pos, ref, alts = _minimize(record.pos, record.ref, record.alt)

    # Left-align: prepend the preceding reference base to every allele
    # and re-minimize.  A move only happens when re-minimization removes
    # a (different) right-hand base, i.e. the extended window represents
    # the same haplotypes; once a step leaves the alleles unchanged the
    # minimum POS has been reached.
    while pos > 1 and _lengths_differ(ref, alts):
        preceding = chromosome[pos - 2].upper()
        next_pos, next_ref, next_alts = _minimize(
            pos - 1,
            preceding + ref,
            tuple(preceding + alt for alt in alts),
        )
        if (next_pos, next_ref, next_alts) == (pos, ref, alts):
            break
        pos, ref, alts = next_pos, next_ref, next_alts

    return replace(record, pos=pos, ref=ref, alt=alts)


def normalize_record(
    record: VcfRecord,
    reference: "Mapping[str, str] | Iterable[SequenceRecord]",
) -> VcfRecord:
    """Normalize one record against *reference*.

    *reference* is either a mapping of CHROM to upper-case reference
    sequence or an iterable of :class:`~genome_variant.sequence_io.SequenceRecord`
    (duplicate identifiers raise :class:`ReferenceMismatchError`).

    The REF fragment at POS is always verified.  Records whose ALT
    contains a symbolic, break-end, spanning (``*``) or missing (``.``)
    allele are returned unchanged.  Otherwise all sequence alleles are
    trimmed of their shared suffix and prefix (one base is always kept)
    and, when allele lengths differ, left-shifted across repeated
    reference bases to the smallest POS representing the same
    haplotypes, re-minimizing after every shift.  ID, QUAL, FILTER,
    INFO, FORMAT, sample text and ALT order are preserved.

    Raises :class:`ReferenceMismatchError` for an absent/duplicate CHROM
    or a REF that disagrees with the reference, and
    :class:`VcfFormatError` for a record that runs past the reference.
    """
    if isinstance(reference, Mapping):
        sequences = dict(reference)
        duplicates: set[str] = set()
    else:
        sequences, duplicates = _build_reference(reference)
    return _normalize_against(record, sequences, duplicates, "")


def normalize_vcf(
    document: VcfFile,
    reference: "Mapping[str, str] | Iterable[SequenceRecord]",
) -> VcfFile:
    """Normalize every record of *document* against *reference*.

    Record order is preserved; see :func:`normalize_record` for the
    per-record rules.  Every record is validated before the normalized
    document is returned, so an error never comes with partial output.
    """
    if isinstance(reference, Mapping):
        sequences = dict(reference)
        duplicates: set[str] = set()
    else:
        sequences, duplicates = _build_reference(reference)

    normalized = tuple(
        _normalize_against(record, sequences, duplicates, document.source)
        for record in document.records
    )
    return VcfFile(document.header, normalized, document.source)


def _record_line(record: VcfRecord) -> str:
    fields = [
        record.chrom,
        str(record.pos),
        record.id,
        record.ref,
        record.alt_text,
        record.qual,
        record.filter,
        record.info,
    ]
    if record.format_text is not None:
        fields.append(record.format_text)
        fields.extend(record.sample_text)
    return "\t".join(fields)


def render_vcf(document: VcfFile) -> str:
    """Serialize *document* to VCF text.

    Output uses tabs and ``"\\n"`` line endings and always ends with
    exactly one trailing newline; a record-less VCF still writes the
    complete header (``##`` lines followed by the ``#CHROM`` line).
    """
    lines = list(document.header.meta_lines)
    lines.append("\t".join(document.header.column_names))
    lines.extend(_record_line(record) for record in document.records)
    return "\n".join(lines) + "\n"


def write_vcf(
    document: VcfFile,
    output: "str | os.PathLike[str] | io.TextIOBase",
) -> None:
    """Write *document* to *output* as VCF text.

    Tabs and ``"\\n"`` are used throughout with exactly one trailing
    newline; an empty-record VCF still writes the complete header.
    """
    text = render_vcf(document)
    if isinstance(output, io.IOBase):
        output.write(text)
    elif isinstance(output, (str, os.PathLike)):
        with open(os.fspath(output), "w", encoding="utf-8", newline="") as stream:
            stream.write(text)
    else:
        raise TypeError("output must be a text path or a text stream")

"""Property tests comparing the DP with exhaustive path enumeration."""

from __future__ import annotations

import itertools

import pytest

from genome_variant.alignment import align_pair
from genome_variant.sequence_io import SequenceRecord

PARAM_SETS = [
    (1, 0, 0, 0),
    (2, 1, 2, 1),
    (2, 3, 5, 2),
]
BASES = "ACG"


def _merge(ops: list[str]) -> str:
    out: list[list] = []
    for op in ops:
        if out and out[-1][1] == op:
            out[-1][0] += 1
        else:
            out.append([1, op])
    return "".join(f"{c}{o}" for c, o in out)


def _score(ops: list[str], match: int, mismatch: int, gap_open: int, gap_extend: int) -> int:
    total = 0
    previous = None
    for op in ops:
        if op in ("=", "X"):
            total += match if op == "=" else -mismatch
        else:
            total -= gap_extend if previous == op else gap_open
        previous = op
    return total


def _paths(m: int, n: int) -> list[tuple[str, ...]]:
    found: list[tuple[str, ...]] = []

    def walk(i: int, j: int, steps: list[str]) -> None:
        if i == m and j == n:
            found.append(tuple(steps))
            return
        if i < m and j < n:
            walk(i + 1, j + 1, steps + ["S"])
        if i < m:
            walk(i + 1, j, steps + ["D"])
        if j < n:
            walk(i, j + 1, steps + ["I"])

    walk(0, 0, [])
    return found


def _columns(path: tuple[str, ...], ref: str, qry: str) -> list[str]:
    ops: list[str] = []
    i = j = 0
    for step in path:
        if step == "S":
            ops.append("=" if ref[i] == qry[j] else "X")
            i += 1
            j += 1
        elif step == "D":
            ops.append("D")
            i += 1
        else:
            ops.append("I")
            j += 1
    return ops


def _best_global(ref: str, qry: str, params: tuple[int, ...]):
    best = None
    for path in _paths(len(ref), len(qry)):
        ops = _columns(path, ref, qry)
        cigar = _merge(ops)
        score = _score(ops, *params)
        if best is None or (-score, cigar) < (-best[0], best[1]):
            best = (score, cigar)
    return best


def _best_local(ref: str, qry: str, params: tuple[int, ...]):
    best = None
    for a in range(len(ref)):
        for b in range(a + 1, len(ref) + 1):
            for c in range(len(qry)):
                for d in range(c + 1, len(qry) + 1):
                    rseg, qseg = ref[a:b], qry[c:d]
                    for path in _paths(len(rseg), len(qseg)):
                        if path[0] != "S":
                            continue
                        ops = _columns(path, rseg, qseg)
                        score = _score(ops, *params)
                        if score <= 0:
                            continue
                        cigar = _merge(ops)
                        key = (-score, a, b, c, d, cigar)
                        if best is None or key < best:
                            best = key
    return best


def _all_sequences(length: int):
    for letters in itertools.product(BASES, repeat=length):
        yield "".join(letters)


def _cases():
    for m in range(4):
        for n in range(4):
            for ref in _all_sequences(m):
                for qry in _all_sequences(n):
                    for params in PARAM_SETS:
                        yield ref, qry, params


@pytest.mark.parametrize("ref,qry,params", list(_cases()))
def test_global_matches_exhaustive_enumeration(ref, qry, params):
    result = align_pair(
        SequenceRecord("r", ref),
        SequenceRecord("q", qry),
        mode="global",
        match_score=params[0],
        mismatch_penalty=params[1],
        gap_open=params[2],
        gap_extend=params[3],
    )
    score, cigar = _best_global(ref, qry, params)
    assert result.score == score
    assert result.cigar == cigar
    assert (result.reference_start, result.reference_end) == (0, len(ref))
    assert (result.query_start, result.query_end) == (0, len(qry))


@pytest.mark.parametrize("ref,qry,params", list(_cases()))
def test_local_matches_exhaustive_enumeration(ref, qry, params):
    result = align_pair(
        SequenceRecord("r", ref),
        SequenceRecord("q", qry),
        mode="local",
        match_score=params[0],
        mismatch_penalty=params[1],
        gap_open=params[2],
        gap_extend=params[3],
    )
    expected = _best_local(ref, qry, params)
    if expected is None:
        assert result.score == 0
        assert result.cigar == ""
        assert (
            result.reference_start,
            result.reference_end,
            result.query_start,
            result.query_end,
        ) == (0, 0, 0, 0)
    else:
        neg_score, a, b, c, d, cigar = expected
        assert result.score == -neg_score
        assert result.cigar == cigar
        assert (
            result.reference_start,
            result.reference_end,
            result.query_start,
            result.query_end,
        ) == (a, b, c, d)
